<?php
namespace App\Http\Controllers;
use App\Http\Controllers\Concerns\ResolvesBranch;use App\Models\PaymentAccount;use Illuminate\Http\Request;
class PaymentAccountController extends Controller {use ResolvesBranch;public function index(Request $r){$branch=$this->branchId($r);return view('payment-accounts.index',['accounts'=>PaymentAccount::with('branch')->when($branch!==0,fn($q)=>$q->where('branch_id',$branch))->get(),'branches'=>$this->branches(),'branchId'=>$branch]);}public function store(Request $r){$branch=$this->branchId($r);abort_if($branch===0,422);PaymentAccount::create($this->validated($r)+['branch_id'=>$branch]);return back()->with('message','Rekening ditambahkan.');}public function update(Request $r,PaymentAccount $paymentAccount){abort_unless($this->canAccessAllBranches()||$paymentAccount->branch_id===auth()->user()->branch_id,403);$paymentAccount->update($this->validated($r));return back()->with('message','Rekening diperbarui.');}private function validated(Request $r){$data=$r->validate(['bank_name'=>'required|string|max:100','account_number'=>'required|string|max:100','account_holder'=>'required|string|max:255','instructions'=>'nullable|string|max:2000','is_active'=>'nullable|boolean']);$data['is_active']=$r->boolean('is_active');return $data;}}
